CREATE DATABASE BAITHI
USE BAITHI

CREATE TABLE SACH (
    MASACH VARCHAR(20) PRIMARY KEY,  -- Mã sách duy nhất
    TENSACH VARCHAR(255) NOT NULL,   -- Tên sách
    THELOAI VARCHAR(100),            -- Thể loại sách
    TACGIA VARCHAR(255),             -- Tác giả sách
    NGXB DATE,                       -- Ngày xuất bản
    NHAXB VARCHAR(255)               -- Đơn vị xuất bản
);

CREATE TABLE DVTOCHUC (
    MADV VARCHAR(20) PRIMARY KEY,     -- Mã đơn vị tổ chức duy nhất
    TENDV VARCHAR(255) NOT NULL,      -- Tên đơn vị tổ chức
    TENNGDD VARCHAR(255),             -- Tên người đại diện đơn vị
    NGTL DATE                         -- Ngày thành lập
);

CREATE TABLE SUKIEN(
	MASK VARCHAR(20) PRIMARY KEY,
	MASACH VARCHAR(20),
	MADV VARCHAR(20),
	TGBD DATETIME,
	TGKT DATETIME,
	DIADIEM VARCHAR(100),
	SLDK INT,
	FOREIGN KEY (MASACH) REFERENCES SACH(MASACH) ON DELETE CASCADE,
	FOREIGN KEY (MADV) REFERENCES DVTOCHUC(MADV) ON DELETE CASCADE
);

CREATE TABLE NGTHAMGIA(
	MANTG VARCHAR(20) PRIMARY KEY,
	TENNTG VARCHAR(50) NOT NULL,
	GIOITINH VARCHAR(5),
	NGSINH DATE,
	NGHENGHIEP VARCHAR(20)
);

CREATE TABLE THAMGIA(
	MANTG VARCHAR(20),
	MASK VARCHAR(20),
	VAITRO VARCHAR(50),
	PRIMARY KEY(MANTG, MASK),
	FOREIGN KEY (MANTG) REFERENCES NGTHAMGIA(MANTG) ON DELETE CASCADE,
	FOREIGN KEY (MASK) REFERENCES SUKIEN(MASK) ON DELETE CASCADE
);

CREATE TABLE DANHGIA(
	MADG VARCHAR(20) PRIMARY KEY,
	MANTG VARCHAR(20),
	MASK VARCHAR(20),
	TGDG DATETIME,
	DIEMSO INT,
	NHANXET VARCHAR(20),
	FOREIGN KEY (MANTG) REFERENCES NGTHAMGIA(MANTG) ON DELETE CASCADE,
	FOREIGN KEY (MASK) REFERENCES SUKIEN(MASK) ON DELETE CASCADE
);

